def table(rows,widths=None):
    data=[[Paragraph(str(c),styles['SmallX']) for c in row] for row in rows]
    t=Table(data,colWidths=widths or [170,170,170],hAlign='LEFT',repeatRows=1)
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),pale),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),1,gold),('LINEBELOW',(0,1),(-1,-1),.4,colors.HexColor('#dce3dc')),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),9),('BOTTOMPADDING',(0,0),(-1,-1),9)]))
